// On-disk encoding of the log. The layout is specified in docs/wal-format.md and
// is a compatibility contract: logs already in production must stay readable.

import { crc32 } from './crc32.mjs';
import { CorruptLogError, WalqError } from './errors.mjs';

export const FORMAT_VERSION = 1;
export const HEADER_SIZE = 20;
export const FRAME_OVERHEAD = 10;
export const MAX_PAYLOAD = 64 * 1024 * 1024;

const FILE_MAGIC = Buffer.from('WALQ', 'latin1');
const FRAME_MAGIC = 0xfbad;
const FRAME_MARK = Buffer.from([0xad, 0xfb]);

export function encodeHeader(generation) {
  const header = Buffer.alloc(HEADER_SIZE);
  FILE_MAGIC.copy(header, 0);
  header.writeUInt16LE(FORMAT_VERSION, 4);
  header.writeUInt32LE(generation, 8);
  header.writeUInt32LE(crc32(header.subarray(0, 16)), 16);
  return header;
}

export function decodeHeader(bytes, file = 'log') {
  if (bytes.length < HEADER_SIZE) {
    throw new CorruptLogError(`${file}: header is missing or short (${bytes.length} bytes)`, { offset: 0 });
  }
  if (!bytes.subarray(0, 4).equals(FILE_MAGIC)) {
    throw new CorruptLogError(`${file}: not a walq log`, { offset: 0 });
  }
  if (bytes.readUInt32LE(16) !== crc32(bytes.subarray(0, 16))) {
    throw new CorruptLogError(`${file}: header checksum mismatch`, { offset: 0 });
  }
  const version = bytes.readUInt16LE(4);
  if (version !== FORMAT_VERSION) {
    throw new CorruptLogError(`${file}: unsupported format version ${version}`, { offset: 0 });
  }
  return { version, generation: bytes.readUInt32LE(8) };
}

export function encodeFrame(record) {
  const payload = Buffer.from(JSON.stringify(record), 'utf8');
  if (payload.length > MAX_PAYLOAD) {
    throw new WalqError(`record of ${payload.length} bytes exceeds the ${MAX_PAYLOAD} byte limit of the log format`, {
      size: payload.length,
    });
  }
  const frame = Buffer.allocUnsafe(FRAME_OVERHEAD + payload.length);
  frame.writeUInt16LE(FRAME_MAGIC, 0);
  frame.writeUInt32LE(payload.length, 2);
  frame.writeUInt32LE(crc32(payload, crc32(frame.subarray(2, 6))), 6);
  payload.copy(frame, FRAME_OVERHEAD);
  return frame;
}

function decodeFrameAt(bytes, pos) {
  const remaining = bytes.length - pos;
  if (remaining < FRAME_OVERHEAD) return { ok: false, reason: 'partial' };
  if (bytes.readUInt16LE(pos) !== FRAME_MAGIC) return { ok: false, reason: 'bad-magic' };
  const length = bytes.readUInt32LE(pos + 2);
  if (length > MAX_PAYLOAD) return { ok: false, reason: 'bad-length' };
  if (remaining < FRAME_OVERHEAD + length) {
    return { ok: false, reason: 'partial', needed: FRAME_OVERHEAD + length };
  }
  const start = pos + FRAME_OVERHEAD;
  const payload = bytes.subarray(start, start + length);
  const expected = bytes.readUInt32LE(pos + 6);
  if (expected !== crc32(payload, crc32(bytes.subarray(pos + 2, pos + 6)))) {
    return { ok: false, reason: 'bad-checksum' };
  }
  try {
    return { ok: true, record: JSON.parse(payload.toString('utf8')), next: start + length };
  } catch {
    return { ok: false, reason: 'bad-payload' };
  }
}

/** True if a complete, checksummed frame starts anywhere after `pos`. */
function validFrameFollows(bytes, pos) {
  let at = bytes.indexOf(FRAME_MARK, pos + 1);
  while (at !== -1) {
    if (decodeFrameAt(bytes, at).ok) return true;
    at = bytes.indexOf(FRAME_MARK, at + 1);
  }
  return false;
}

/**
 * Walks frames starting at the beginning of `bytes`, which sit at `baseOffset`
 * in the file. Returns the decoded frames, the file offset just after the last
 * good one, and `tail` when the bytes after that are not a complete frame.
 *
 * `bytes` must run to the end of the file. A bad frame is a torn tail (a write
 * that was cut off, whatever it left behind) only when nothing after it decodes.
 * If a valid frame follows, the bad bytes sit inside acknowledged data, and that
 * is damage: CorruptLogError. Valid UTF-8 never contains the byte FB, so a
 * payload cannot fake a frame start. A frame whose checksum passes but whose
 * payload is not JSON cannot be a torn write either.
 */
export function scanFrames(bytes, baseOffset = 0) {
  const frames = [];
  let pos = 0;
  let tail = null;
  while (pos < bytes.length) {
    const decoded = decodeFrameAt(bytes, pos);
    if (!decoded.ok) {
      if (decoded.reason === 'bad-payload' || validFrameFollows(bytes, pos)) {
        throw new CorruptLogError(
          `corrupt record at offset ${baseOffset + pos} (${decoded.reason})`,
          { offset: baseOffset + pos, reason: decoded.reason },
        );
      }
      tail = {
        offset: baseOffset + pos,
        reason: decoded.reason,
        bytes: bytes.length - pos,
        needed: decoded.needed ?? null,
      };
      break;
    }
    frames.push({ offset: baseOffset + pos, size: decoded.next - pos, record: decoded.record });
    pos = decoded.next;
  }
  return { frames, end: baseOffset + pos, tail };
}

// The log file itself: a header, then checksummed frames, written only by the
// process holding the queue lock.

import path from 'node:path';
import { decodeHeader, encodeFrame, encodeHeader, HEADER_SIZE, scanFrames } from './frame.mjs';
import { hit, isArmed } from './failpoints.mjs';

// Bounds memory when a process has fallen far behind: the log is read and
// applied a chunk at a time. A frame bigger than a chunk is read whole.
const SCAN_CHUNK = 1024 * 1024;

export class Wal {
  constructor(file, ops) {
    this.file = file;
    this.ops = ops;
  }

  exists() {
    return this.ops.exists(this.file);
  }

  /**
   * Creates an empty log. The header is synced before the file gets its final
   * name, so the log appears complete or not at all, even across power loss.
   */
  create(generation = 1) {
    const staging = `${this.file}.init`;
    this.ops.create(staging);
    this.ops.writeAt(staging, encodeHeader(generation), 0);
    this.ops.sync(staging);
    this.ops.rename(staging, this.file);
    hit('wal.after-create', {});
    this.ops.syncDir(path.dirname(this.file));
  }

  readHeader() {
    return decodeHeader(this.ops.read(this.file, 0, HEADER_SIZE), this.file);
  }

  /**
   * Decodes everything from `offset` to the end of the file, passing the frames
   * to `visit` a chunk at a time. Returns where the last good frame ends and the
   * incomplete tail after it, if any (see scanFrames).
   */
  scanFrom(offset, visit) {
    const size = this.ops.size(this.file);
    let pos = offset;
    let want = SCAN_CHUNK;
    for (;;) {
      const bytes = this.ops.read(this.file, pos, want);
      const atEnd = pos + bytes.length >= size;
      const scan = scanFrames(bytes, pos);
      if (scan.frames.length) visit(scan.frames);
      pos = scan.end;
      if (atEnd) return { end: pos, tail: scan.tail };
      if (!scan.tail) {
        want = SCAN_CHUNK;
      } else if (scan.tail.reason === 'partial' && scan.tail.needed) {
        want = Math.max(scan.tail.needed, SCAN_CHUNK);
      } else if (scan.tail.reason === 'partial') {
        want = SCAN_CHUNK;
      } else {
        // The chunk ended before the file did, so whether this is a torn tail
        // or damage depends on what follows. Look at all of it.
        want = Infinity;
      }
    }
  }

  truncate(length) {
    this.ops.truncate(this.file, length);
  }

  /** Writes records at `at`, the end of the good log. Returns the new end offset. */
  append(records, { sync = true, at } = {}) {
    const type = records[0]?.t;
    const bytes = Buffer.concat(records.map(encodeFrame));
    hit('wal.before-append', { type });
    if (isArmed('wal.mid-append')) {
      const half = bytes.length >> 1;
      this.ops.writeAt(this.file, bytes.subarray(0, half), at);
      hit('wal.mid-append', { type });
      this.ops.writeAt(this.file, bytes.subarray(half), at + half);
    } else {
      this.ops.writeAt(this.file, bytes, at);
    }
    hit('wal.after-write', { type });
    if (sync) this.ops.sync(this.file);
    hit('wal.after-fsync', { type });
    return at + bytes.length;
  }
}

