// The queue's state is a pure fold over the log. Replaying the same records must
// give the same state in every process, at any time. Nothing here may read a
// clock: every time comes from the records.

import { loadSnapshot } from './snapshot.mjs';

export function createState() {
  return { jobs: new Map(), idem: new Map(), seq: 0, completionSeq: 0 };
}

function requeue(job, availableAt, error) {
  job.status = 'ready';
  job.availableAt = availableAt;
  job.lease = null;
  job.lastError = error ?? job.lastError;
}

function holdsLease(job, fence) {
  return job.status === 'leased' && job.lease?.fence === fence;
}

export function applyRecord(state, rec) {
  if (rec.t === 'snapshot') {
    loadSnapshot(state, rec);
    return;
  }
  if (rec.t === 'enqueue') {
    state.seq += 1;
    state.jobs.set(rec.id, {
      id: rec.id,
      type: rec.type,
      payload: rec.payload,
      key: rec.key ?? null,
      priority: rec.priority ?? 0,
      status: 'ready',
      attempts: 0,
      fence: 0,
      maxAttempts: rec.maxAttempts,
      availableAt: rec.availableAt,
      lease: null,
      result: null,
      lastError: null,
      enqueuedAt: rec.at,
      completedAt: null,
      completionSeq: null,
      seq: state.seq,
    });
    if (rec.key) state.idem.set(rec.key, { id: rec.id, at: rec.at });
    return;
  }

  const job = state.jobs.get(rec.id);
  if (!job) return;

  // A record about an attempt that is no longer the current one has no effect.
  // The queue never writes one, but two processes racing used to, and a late
  // record must not bring a finished job back to life.
  switch (rec.t) {
    case 'claim':
      if (job.status !== 'ready') break;
      job.status = 'leased';
      job.attempts += 1;
      job.fence = rec.fence;
      job.lease = { worker: rec.worker, fence: rec.fence, until: rec.leaseUntil };
      break;
    case 'heartbeat':
      if (holdsLease(job, rec.fence)) job.lease.until = rec.leaseUntil;
      break;
    case 'complete':
      if (!holdsLease(job, rec.fence)) break;
      state.completionSeq += 1;
      job.status = 'done';
      job.lease = null;
      job.result = rec.result ?? null;
      job.completedAt = rec.at;
      job.completionSeq = state.completionSeq;
      break;
    case 'fail':
    case 'expire':
      if (!holdsLease(job, rec.fence)) break;
      requeue(job, rec.at + rec.delayMs, rec.error);
      break;
    case 'release':
      if (!holdsLease(job, rec.fence)) break;
      requeue(job, rec.at, rec.error);
      break;
    case 'dead':
      if (!holdsLease(job, rec.fence)) break;
      job.status = 'dead';
      job.lease = null;
      job.lastError = rec.error ?? job.lastError;
      job.completedAt = rec.at;
      break;
    case 'cancel':
      if (job.status !== 'ready' && !holdsLease(job, rec.fence)) break;
      job.status = 'cancelled';
      job.lease = null;
      job.lastError = rec.error ?? job.lastError;
      job.completedAt = rec.at;
      break;
    case 'requeue':
      if (job.status !== 'dead') break;
      // The fence is not reset: a token is never issued twice for a job.
      job.attempts = 0;
      job.completedAt = null;
      requeue(job, rec.at, job.lastError);
      break;
    default:
      // Unknown record types come from a newer writer; ignoring them keeps old
      // tools able to read the rest of the log.
      break;
  }
}

// A compacted log starts with one snapshot record holding the state it replaces.

import { isPastRetention } from './retention.mjs';

function serializeJob(job) {
  return {
    id: job.id,
    type: job.type,
    payload: job.payload,
    key: job.key,
    priority: job.priority,
    status: job.status,
    attempts: job.attempts,
    fence: job.fence,
    maxAttempts: job.maxAttempts,
    availableAt: job.availableAt,
    lease: job.lease,
    result: job.result,
    lastError: job.lastError,
    enqueuedAt: job.enqueuedAt,
    completedAt: job.completedAt,
    completionSeq: job.completionSeq,
    seq: job.seq,
  };
}

/**
 * Builds the snapshot record, dropping terminal jobs past their retention. Keys
 * outlive the jobs that made them, so the snapshot carries every key still in
 * its time to live, with the outcome to hand back if its job is gone.
 */
export function buildSnapshot(state, now, config) {
  const kept = [];
  for (const job of state.jobs.values()) {
    if (!isPastRetention(job, now, config)) kept.push(job);
  }

  const idem = [];
  for (const [key, entry] of state.idem) {
    if (now - entry.at >= config.idempotencyTtlMs) continue;
    const job = state.jobs.get(entry.id);
    idem.push({
      key,
      id: entry.id,
      at: entry.at,
      status: job?.status ?? entry.status ?? 'done',
      result: job ? job.result ?? null : entry.result ?? null,
    });
  }

  return {
    t: 'snapshot',
    at: now,
    seq: state.seq,
    completionSeq: state.completionSeq,
    jobs: kept.map(serializeJob),
    idem,
  };
}

export function loadSnapshot(state, rec) {
  state.seq = rec.seq;
  state.completionSeq = rec.completionSeq ?? 0;
  state.jobs = new Map();
  state.idem = new Map();
  for (const job of rec.jobs) {
    state.jobs.set(job.id, {
      ...job,
      priority: job.priority ?? 0,
      attempts: job.attempts ?? 0,
      fence: job.fence ?? job.lease?.fence ?? 0,
      completionSeq: job.completionSeq ?? null,
    });
  }
  if (rec.idem) {
    for (const entry of rec.idem) state.idem.set(entry.key, { id: entry.id, at: entry.at, status: entry.status, result: entry.result });
  } else {
    // Older snapshots did not carry keys: rebuild them from the jobs, the newest job winning.
    for (const job of rec.jobs) {
      const known = job.key ? state.idem.get(job.key) : null;
      if (job.key && (!known || state.jobs.get(known.id).seq < job.seq)) {
        state.idem.set(job.key, { id: job.id, at: job.enqueuedAt });
      }
    }
  }
}

// Idempotency keys map a caller-chosen key to the job it created.

/** Returns what a repeat enqueue with `key` should see, or null if the key is free. */
export function lookupKey(state, key, now, ttlMs) {
  const entry = state.idem.get(key);
  if (!entry) return null;
  if (now - entry.at >= ttlMs) return null;
  const job = state.jobs.get(entry.id);
  if (job) return { id: job.id, status: job.status, result: job.result ?? null };
  return { id: entry.id, status: entry.status ?? 'done', result: entry.result ?? null };
}

// Replaces the log with a one-record log holding the current state. Runs under
// the queue lock. docs/compaction.md describes the protocol.

import path from 'node:path';
import { encodeFrame, encodeHeader } from './frame.mjs';
import { hit } from './failpoints.mjs';
import { buildSnapshot } from './snapshot.mjs';

export function compactionTempPath(walFile) {
  return `${walFile}.compact`;
}

/**
 * Writes and installs the next generation of the log. Returns the snapshot and
 * the size of the new file. If this throws before the rename, the old log is
 * still in place and the temp file is gone.
 */
export function compactLog({ wal, ops, state, generation, now, config }) {
  const nextGeneration = generation + 1;
  const snapshot = buildSnapshot(state, now, config);
  const bytes = Buffer.concat([encodeHeader(nextGeneration), encodeFrame(snapshot)]);
  const tempPath = compactionTempPath(wal.file);

  try {
    // We hold the queue lock, so any temp file already here is the leftover of a
    // compaction that was killed or failed. Nobody else can be using it.
    ops.unlink(tempPath);
    ops.create(tempPath);
    ops.writeAt(tempPath, bytes, 0);
    // The bytes must be on disk before the file takes the log's name, or a power
    // cut right after the rename leaves a log that is empty.
    ops.sync(tempPath);
    hit('compact.after-tmp-write', { generation: nextGeneration });
    hit('compact.before-rename', { generation: nextGeneration });
    ops.rename(tempPath, wal.file);
    hit('compact.after-rename', { generation: nextGeneration });
    ops.syncDir(path.dirname(wal.file));
  } catch (err) {
    err.message = `compaction failed: ${err.message}`;
    try {
      ops.unlink(tempPath);
    } catch {
      // The next compaction removes it first. The original error is the one to report.
    }
    throw err;
  }

  return { snapshot, generation: nextGeneration, size: bytes.length };
}

// Store: the replayed state plus the rules for reading and writing the log.
// Every read of shared state and every write happens inside withLock(), which
// first brings this process up to date with whatever other processes wrote.

import path from 'node:path';
import { compactLog } from './compactor.mjs';
import { QueueClosedError } from './errors.mjs';
import { FORMAT_VERSION, HEADER_SIZE } from './frame.mjs';
import { createFileOps, ensureDir } from './fsops.mjs';
import { acquireLock } from './lock.mjs';
import { createLogger } from './logger.mjs';
import { applyRecord, createState } from './state.mjs';
import { Wal } from './wal.mjs';

export const WAL_FILE = 'wal.log';
export const LOCK_FILE = 'queue.lock';

const log = createLogger('store');

export class Store {
  constructor(dir, config) {
    this.dir = dir;
    this.config = config;
    this.clock = config.clock;
    this.ops = createFileOps();
    this.wal = new Wal(path.join(dir, WAL_FILE), this.ops);
    this.lockPath = path.join(dir, LOCK_FILE);
    this.state = createState();
    this.generation = null;
    this.offset = HEADER_SIZE;
    this.snapshotBytes = 0;
    this.retryCompactionAt = 0;
    this.tornTailsDropped = 0;
    this.lastCompactionError = null;
    this.closed = false;
    this.holdingLock = false;
  }

  open() {
    ensureDir(this.dir);
    this.#locked(() => {
      if (!this.wal.exists()) this.wal.create();
      this.catchUp();
    });
  }

  close() {
    this.closed = true;
  }

  #locked(fn) {
    if (this.holdingLock) throw new Error('queue lock is not reentrant');
    const release = acquireLock(this.lockPath, { timeoutMs: this.config.lockTimeoutMs });
    this.holdingLock = true;
    try {
      return fn();
    } finally {
      this.holdingLock = false;
      release();
    }
  }

  withLock(fn) {
    if (this.closed) throw new QueueClosedError();
    return this.#locked(() => {
      this.catchUp();
      return fn();
    });
  }

  /** Brings this.state up to date with the log without doing anything else. */
  refresh() {
    this.withLock(() => {});
  }

  #reset(generation) {
    this.state = createState();
    this.offset = HEADER_SIZE;
    this.snapshotBytes = 0;
    this.retryCompactionAt = 0;
    this.generation = generation;
  }

  /**
   * Reads the log up to its end and applies it. Must hold the lock: nobody else
   * is writing, so whatever follows the last good record is a write that was cut
   * off. It is removed here, so that nothing written later lands behind it.
   */
  catchUp() {
    const header = this.wal.readHeader();
    // Another process compacted if the generation moved, however big the new
    // log is. A shorter file alone means the same thing.
    if (
      this.generation === null ||
      header.generation !== this.generation ||
      this.ops.size(this.wal.file) < this.offset
    ) {
      this.#reset(header.generation);
    }

    const { end, tail } = this.wal.scanFrom(this.offset, (frames) => {
      for (const frame of frames) {
        applyRecord(this.state, frame.record);
        if (frame.record.t === 'snapshot') this.snapshotBytes = frame.size;
        this.offset = frame.offset + frame.size;
      }
    });
    this.offset = end;

    if (tail) {
      this.wal.truncate(end);
      this.tornTailsDropped += 1;
      log.warn('dropped incomplete tail', { offset: end, reason: tail.reason, bytes: tail.bytes });
    }
  }

  /** Must be called inside withLock(). */
  append(records, options) {
    this.offset = this.wal.append(records, { ...options, at: this.offset });
    // Apply what a reader of the log would see, so every process holds the same state.
    for (const record of records) applyRecord(this.state, JSON.parse(JSON.stringify(record)));
  }

  /** Must be called inside withLock(). */
  compact() {
    const bytesBefore = this.offset;
    let result;
    try {
      result = compactLog({
        wal: this.wal,
        ops: this.ops,
        state: this.state,
        generation: this.generation,
        now: this.clock.now(),
        config: this.config,
      });
    } catch (err) {
      // The new log may already be in place if the failure came after the rename.
      // Dropping what we hold makes the next catch-up read whichever log is there.
      this.generation = null;
      throw err;
    }
    const { snapshot, generation, size } = result;
    this.state = createState();
    applyRecord(this.state, snapshot);
    this.generation = generation;
    this.offset = size;
    this.snapshotBytes = size - HEADER_SIZE;
    this.retryCompactionAt = 0;
    log.info('compacted', { generation, bytesBefore, bytesAfter: size });
    return { generation, bytesBefore, bytesAfter: size, jobs: this.state.jobs.size };
  }

  /**
   * Compacts when the log has outgrown the threshold and has doubled since the
   * last compaction, so that a live state bigger than the threshold is not
   * rewritten on every write. A failure here must not fail the operation that
   * triggered it, because that operation has committed; the next attempt waits
   * for the log to grow a little.
   */
  maybeCompact() {
    const threshold = this.config.compactAfterBytes;
    if (!threshold) return;
    const compacted = HEADER_SIZE + this.snapshotBytes;
    if (this.offset < Math.max(threshold, 2 * compacted, this.retryCompactionAt)) return;
    try {
      this.compact();
      this.lastCompactionError = null;
    } catch (err) {
      this.lastCompactionError = err;
      this.retryCompactionAt = this.offset + Math.max(1, threshold >> 2);
      log.warn('compaction failed', { error: err.message });
    }
  }

  describe() {
    return {
      format: FORMAT_VERSION,
      generation: this.generation,
      logBytes: this.offset,
      tornTailsDropped: this.tornTailsDropped,
      lastCompactionError: this.lastCompactionError?.message ?? null,
    };
  }
}

