// Opens the log only for the instant of each poll. A handle kept open between
// polls would stop compaction from replacing the file on Windows, and would keep
// reading the old log after a compaction anyway. A change of generation, or a
// shorter file, means the log was replaced: start again from its beginning.
function tail(dir) {
  const file = path.join(dir, WAL_FILE);
  let generation = null;
  let offset = HEADER_SIZE;
  const poll = () => {
    let bytes;
    try {
      bytes = fs.readFileSync(file);
    } catch (err) {
      if (err.code === 'ENOENT') return;
      throw err;
    }
    const header = decodeHeader(bytes, file);
    if (generation !== header.generation || bytes.length < offset) {
      if (generation !== null) console.log(`log replaced, now generation ${header.generation}`);
      generation = header.generation;
      offset = HEADER_SIZE;
    }
    const { frames, end } = scanFrames(bytes.subarray(offset), offset);
    for (const frame of frames) console.log(describeRecord(frame.record));
    offset = end;
  };
  const timer = setInterval(() => {
    try {
      poll();
    } catch (err) {
      clearInterval(timer);
      console.error(`${err.name}: ${err.message}`);
      process.exitCode = 1;
    }
  }, 200);
  process.on('SIGINT', () => clearInterval(timer));
}

